```javascript
function debounce(func, wait) {
    let timeoutId;
    let isDebouncing = false;

    return function(...args) {
        if (isDebouncing) {
            clearTimeout(timeoutId);
            isDebouncing = false;
        }

        isDebouncing = true;
        timeoutId = setTimeout(() => {
            func(...args);
            isDebouncing = false;
        }, wait);
    };
}

